#!/usr/bin/env python3
from __future__ import annotations
import argparse
from pathlib import Path
def main():
 p=argparse.ArgumentParser();p.add_argument('--claim-map',type=Path,required=True);p.add_argument('--limitations',type=Path,required=True);p.add_argument('--output',type=Path,required=True);a=p.parse_args();text='''# Reviewer Question Bank\n\n## Why not use a linear stage chain?\nThe frozen manual graph represents two legal orders rather than collapsing them to one sequence; controlled evidence is qualified by its limited support.\n\n## Why use a manual graph?\nManual graph structure remains the stated main method. Automatic graph exploration is appendix-only and is not claimed as a contribution.\n\n## How does recovery avoid reward hacking?\nRecovery credit is bounded by accumulated failure debt; the locked configuration has eta=0 and beta=0, so nonzero loop and uncertainty terms are not claimed.\n\n## Why is policy not a main conclusion?\nThe frozen policy evidence is secondary/mixed, not stable across seeds.\n\n## Why not claim unseen-order generalization?\nThe real order-holdout rerun did not meet the predeclared extension support condition.\n\n## What are the data limitations?\nThe task/data coverage is finite; controlled symbolic stress is not real-robot generalization.\n\n## How does this differ from planners or stage-transition rewards?\nThe scope is a graph-structured reward representation evaluated on the locked benchmark, not a claim about a general planner or a universally superior transition reward.\n''';a.output.parent.mkdir(parents=True,exist_ok=True);a.output.write_text(text,encoding='utf-8')
if __name__=='__main__':main()
